39	// FNV-1a 64 位内容哈希：同地图必同 hash、异地图（尺寸/分辨率/栅格数据任一
40	// 变化）必异 hash，供调度侧版本门禁（expected_map_hash）比对。
41	std::string ComputeMapHash(const MapGrid& grid) {
42	  uint64_t h = 14695981039346656037ULL;  // FNV-1a offset basis
43	  const auto mix = [&h](const void* bytes, std::size_t n) {
44	    const auto* p = static_cast<const uint8_t*>(bytes);
45	    for (std::size_t i = 0; i < n; ++i) {
46	      h ^= p[i];
47	      h *= 1099511628211ULL;  // FNV prime
48	    }
49	  };
50	  mix(&grid.width, sizeof(grid.width));
51	  mix(&grid.height, sizeof(grid.height));
52	  mix(&grid.resolution, sizeof(grid.resolution));
53	  if (!grid.data.empty()) {
54	    mix(grid.data.data(), grid.data.size());
55	  }
56	  std::ostringstream out;
57	  out << "fnv1a64_" << std::hex << std::setfill('0') << std::setw(16) << h;
58	  return out.str();
59	}
