61	// 站点锚点摘要：markers 内容变化（新增/移动站点）也要触发重新生成，
62	// 否则同图重复消息会被跳过。仅摘要参与 hash，不额外读文件系统状态。
63	std::string ComputeAnchorsDigest(const std::vector<AnchorStation>& anchors) {
64	  uint64_t h = 14695981039346656037ULL;
65	  const auto mix_str = [&h](const std::string& s) {
66	    for (const char c : s) {
67	      h ^= static_cast<uint8_t>(c);
68	      h *= 1099511628211ULL;
69	    }
70	    h ^= 0xFFu;  // 分隔符，防 "ab"+"c" 与 "a"+"bc" 摘要碰撞
71	    h *= 1099511628211ULL;
72	  };
73	  const auto mix_double = [&h](double v) {
74	    uint64_t u = 0;
75	    static_assert(sizeof(u) == sizeof(v), "double must be 64-bit");
76	    std::memcpy(&u, &v, sizeof(v));
77	    for (int i = 0; i < 8; ++i) {
78	      h ^= static_cast<uint8_t>(u >> (i * 8));
79	      h *= 1099511628211ULL;
80	    }
81	  };
82	  for (const auto& a : anchors) {
83	    mix_str(a.id);
84	    mix_str(a.type);
85	    mix_double(a.x);
86	    mix_double(a.y);
87	    mix_double(a.yaw);
88	  }
89	  std::ostringstream out;
90	  out << std::hex << std::setfill('0') << std::setw(16) << h;
91	  return out.str();
92	}
