94	// double -> YAML 文本：max_digits10 保证往返解析不丢精度。
95	std::string FormatDouble(double v) {
96	  std::ostringstream out;
97	  out << std::setprecision(std::numeric_limits<double>::max_digits10) << v;
98	  return out.str();
99	}
