130	MapIngestNode::MapIngestNode(const rclcpp::NodeOptions& options)
131	    : rclcpp::Node("map_ingest_node", options) {
132	  declare_parameter<std::string>("map_topic", "/map");
133	  declare_parameter<std::string>("markers_file", "");
134	  declare_parameter<std::string>("output_stations_file", "config/generated/stations.yaml");
135	  declare_parameter<double>("robot_radius_m", 0.25);
136	  declare_parameter<double>("safety_margin_m", 0.05);
137	  declare_parameter<double>("min_branch_length_m", 0.5);
138	  declare_parameter<double>("max_snap_dist_m", 2.0);
139	  declare_parameter<bool>("publish_markers", true);
140	  declare_parameter<std::string>("marker_topic", "/dispatcher/topology_markers");
141	
142	  map_topic_ = get_parameter("map_topic").as_string();
143	  markers_file_ = get_parameter("markers_file").as_string();
144	  output_stations_file_ = get_parameter("output_stations_file").as_string();
145	  robot_radius_m_ = get_parameter("robot_radius_m").as_double();
146	  safety_margin_m_ = get_parameter("safety_margin_m").as_double();
147	  min_branch_length_m_ = get_parameter("min_branch_length_m").as_double();
148	  max_snap_dist_m_ = get_parameter("max_snap_dist_m").as_double();
149	  publish_markers_ = get_parameter("publish_markers").as_bool();
150	  marker_topic_ = get_parameter("marker_topic").as_string();
151	
152	  // transient_local + reliable：与 nav2_map_server / 静态地图发布者的
153	  // latched 语义对接——即使 map_ingest_node 启动晚于 map_server 也能收到地图。
154	  map_sub_ = create_subscription<OccupancyGrid>(
155	      map_topic_, rclcpp::QoS(rclcpp::KeepLast(1)).transient_local().reliable(),
156	      std::bind(&MapIngestNode::MapCallback, this, std::placeholders::_1));
157	
158	  // transient_local：RViz 晚启动也能立即看到完整拓扑。
159	  marker_pub_ = create_publisher<visualization_msgs::msg::MarkerArray>(
160	      marker_topic_, rclcpp::QoS(rclcpp::KeepLast(1)).transient_local());
161	
162	  RCLCPP_INFO(get_logger(),
163	              "MapIngestNode started: map_topic=%s markers_file='%s' output='%s' "
164	              "(robot_radius=%.2fm margin=%.2fm min_branch=%.2fm max_snap=%.2fm)",
165	              map_topic_.c_str(), markers_file_.c_str(), output_stations_file_.c_str(),
166	              robot_radius_m_, safety_margin_m_, min_branch_length_m_, max_snap_dist_m_);
167	}
