169	std::vector<AnchorStation> MapIngestNode::LoadAnchors() const {
170	  std::vector<AnchorStation> anchors;
171	  if (markers_file_.empty()) {
172	    return anchors;
173	  }
174	  std::error_code ec;
175	  if (!std::filesystem::exists(markers_file_, ec)) {
176	    RCLCPP_WARN(get_logger(), "markers_file '%s' does not exist yet; waiting",
177	                markers_file_.c_str());
178	    return anchors;
179	  }
180	  try {
181	    const YAML::Node root = YAML::LoadFile(markers_file_);
182	    if (!root["anchors"] || !root["anchors"].IsSequence()) {
183	      RCLCPP_WARN(get_logger(), "markers_file '%s' has no 'anchors' list; waiting",
184	                  markers_file_.c_str());
185	      return anchors;
186	    }
187	    for (const auto& node : root["anchors"]) {
188	      AnchorStation anchor;
189	      anchor.id = node["id"].as<std::string>();
190	      anchor.type = node["type"].as<std::string>("normal");
191	      anchor.x = node["x"].as<double>();
192	      anchor.y = node["y"].as<double>();
193	      anchor.yaw = node["yaw"].as<double>(0.0);
194	      if (anchor.id.empty()) {
195	        RCLCPP_WARN(get_logger(), "markers_file '%s' contains an anchor with empty id; skipped",
196	                    markers_file_.c_str());
197	        continue;
198	      }
199	      anchors.push_back(std::move(anchor));
200	    }
201	  } catch (const std::exception& e) {
202	    RCLCPP_ERROR(get_logger(), "Failed to parse markers_file '%s': %s",
203	                 markers_file_.c_str(), e.what());
204	    anchors.clear();
205	  }
206	  return anchors;
207	}
