209	std::string MapIngestNode::SerializeCatalog(const StationCatalog& catalog) {
210	  // 与 LoadStationCatalog 的逐行严格解析 schema 对齐（Task 1）：
211	  // version(map_hash/graph_version) -> stations -> road_nodes -> edges(polyline)。
212	  std::ostringstream out;
213	  out << "version:\n";
214	  out << "  map_hash: " << Quote(catalog.map_hash) << "\n";
215	  out << "  graph_version: " << Quote(catalog.graph_version) << "\n";
216	
217	  out << "stations:\n";
218	  for (const auto& station : catalog.stations) {
219	    out << "  - id: " << Quote(station.id) << "\n";
220	    out << "    x: " << FormatDouble(station.x) << "\n";
221	    out << "    y: " << FormatDouble(station.y) << "\n";
222	    out << "    yaw: " << FormatDouble(station.yaw) << "\n";
223	    out << "    type: " << Quote(station.type) << "\n";
224	  }
225	
226	  out << "road_nodes:\n";
227	  for (const auto& node : catalog.road_nodes) {
228	    out << "  - id: " << Quote(node.id) << "\n";
229	    out << "    x: " << FormatDouble(node.x) << "\n";
230	    out << "    y: " << FormatDouble(node.y) << "\n";
231	    out << "    yaw: " << FormatDouble(node.yaw) << "\n";
232	  }
233	
234	  out << "edges:\n";
235	  for (const auto& edge : catalog.edges) {
236	    out << "  - from: " << Quote(edge.from) << "\n";
237	    out << "    to: " << Quote(edge.to) << "\n";
238	    out << "    distance_m: " << FormatDouble(edge.distance_m) << "\n";
239	    out << "    bidirectional: " << (edge.bidirectional ? "true" : "false") << "\n";
240	    out << "    enabled: " << (edge.enabled ? "true" : "false") << "\n";
241	    out << "    polyline:\n";
242	    for (const auto& point : edge.polyline) {
243	      out << "      - [" << FormatDouble(point.first) << ", " << FormatDouble(point.second)
244	          << "]\n";
245	    }
246	  }
247	  return out.str();
248	}
