250	bool MapIngestNode::WriteCatalogAtomic(const StationCatalog& catalog) const {
251	  const std::filesystem::path final_path(output_stations_file_);
252	  const std::filesystem::path tmp_path(final_path.string() + ".tmp");
253	  std::error_code ec;
254	
255	  if (final_path.has_parent_path()) {
256	    std::filesystem::create_directories(final_path.parent_path(), ec);
257	    if (ec) {
258	      RCLCPP_ERROR(get_logger(), "Cannot create directory for %s: %s",
259	                   final_path.parent_path().string().c_str(), ec.message().c_str());
260	      return false;
261	    }
262	  }
263	
264	  {
265	    std::ofstream out(tmp_path, std::ios::trunc);
266	    if (!out) {
267	      RCLCPP_ERROR(get_logger(), "Cannot open temp file %s for writing", tmp_path.c_str());
268	      return false;
269	    }
270	    out << SerializeCatalog(catalog);
271	    out.flush();
272	    if (!out) {
273	      out.close();
274	      std::filesystem::remove(tmp_path, ec);
275	      RCLCPP_ERROR(get_logger(), "Failed writing temp file %s", tmp_path.c_str());
276	      return false;
277	    }
278	  }
279	
280	  // 回读校验：tmp 文件必须能被调度侧的严格解析器 LoadStationCatalog 接受，
281	  // 否则删除 tmp、保留旧文件——绝不让半截/坏目录进入热重载路径。
282	  if (!LoadStationCatalog(tmp_path)) {
283	    std::filesystem::remove(tmp_path, ec);
284	    RCLCPP_ERROR(get_logger(),
285	                 "Round-trip validation failed for %s; generated YAML is not parseable "
286	                 "by LoadStationCatalog (keeping existing catalog)",
287	                 tmp_path.c_str());
288	    return false;
289	  }
290	
291	  // 同目录内 rename(2) 为原子操作：调度端要么看到旧文件要么看到新文件。
292	  std::filesystem::rename(tmp_path, final_path, ec);
293	  if (ec) {
294	    std::filesystem::remove(tmp_path, ec);
295	    RCLCPP_ERROR(get_logger(), "Atomic rename %s -> %s failed: %s", tmp_path.c_str(),
296	                 final_path.c_str(), ec.message().c_str());
297	    return false;
298	  }
299	  return true;
300	}
