302	void MapIngestNode::MapCallback(const OccupancyGrid::SharedPtr msg) {
303	  if (msg->info.width == 0 || msg->info.height == 0) {
304	    RCLCPP_WARN(get_logger(), "Ignoring invalid map: width=%u height=%u", msg->info.width,
305	                msg->info.height);
306	    return;
307	  }
308	  const std::size_t expected_cells =
309	      static_cast<std::size_t>(msg->info.width) * msg->info.height;
310	  if (msg->data.size() != expected_cells) {
311	    RCLCPP_WARN(get_logger(), "Ignoring malformed map: data size %zu != %u x %u",
312	                msg->data.size(), msg->info.width, msg->info.height);
313	    return;
314	  }
315	
316	  // ---- ① OccupancyGrid -> 核心库 MapGrid ----
317	  MapGrid grid;
318	  grid.width = msg->info.width;
319	  grid.height = msg->info.height;
320	  grid.resolution = msg->info.resolution;
321	  grid.origin_x = msg->info.origin.position.x;
322	  grid.origin_y = msg->info.origin.position.y;
323	  grid.origin_yaw = amr_dispatcher_core::path_tracking::YawFromQuaternion(
324	      msg->info.origin.orientation.z, msg->info.origin.orientation.w);
325	  grid.data.assign(msg->data.begin(), msg->data.end());
326	
327	  // ---- ② 加载站点锚点（markers.yaml anchors 段） ----
328	  const std::vector<AnchorStation> anchors = LoadAnchors();
329	  if (anchors.empty()) {
330	    RCLCPP_ERROR(get_logger(),
331	                 "No station anchors available (markers_file: '%s'); waiting for a valid "
332	                 "markers file before generating the catalog",
333	                 markers_file_.c_str());
334	    return;
335	  }
336	
337	  // 同图 + 同锚点重复消息：跳过重写，避免无谓触发调度侧热重载。
338	  const std::string map_hash = ComputeMapHash(grid);
339	  const std::string ingest_hash = map_hash + "#" + ComputeAnchorsDigest(anchors);
340	  if (ingest_hash == last_ingest_hash_) {
341	    RCLCPP_DEBUG(get_logger(), "Map and anchors unchanged (%s); skipping re-ingest",
342	                 map_hash.c_str());
343	    return;
344	  }
345	
346	  // ---- ③ 核心库算法流水线 ----
347	  SafetyFilterConfig safety_cfg;
348	  safety_cfg.robot_radius_m = robot_radius_m_;
349	  safety_cfg.safety_margin_m = safety_margin_m_;
350	
351	  PruneConfig prune_cfg;
352	  prune_cfg.min_branch_length_m = min_branch_length_m_;
353	  prune_cfg.resolution = grid.resolution;
354	
355	  TopologyBuilderConfig builder_cfg;
356	  builder_cfg.max_snap_dist_m = max_snap_dist_m_;
357	  builder_cfg.map_hash = map_hash;
358	  builder_cfg.graph_version = "v1";
359	
360	  const BinaryGrid safety_grid = amr_dispatcher_core::planning::FilterSafetySpace(grid, safety_cfg);
361	  const BinaryGrid skeleton = amr_dispatcher_core::planning::ZhangSuenThinning(safety_grid);
362	
363	  std::vector<PixelCoord> protected_points;
364	  protected_points.reserve(anchors.size());
365	  for (const auto& anchor : anchors) {
366	    protected_points.push_back(
367	        amr_dispatcher_core::planning::WorldToPixel(WorldCoord{anchor.x, anchor.y}, grid));
368	  }
369	  const BinaryGrid pruned =
370	      amr_dispatcher_core::planning::PruneSkeletonProtected(skeleton, protected_points, prune_cfg);
371	
372	  // ---- ④ 拓扑构建与站点吸附 ----
373	  const auto result = amr_dispatcher_core::planning::BuildTopologyCatalog(pruned, grid, anchors,
374	                                                                          builder_cfg);
375	  if (!result.success) {
376	    RCLCPP_ERROR(get_logger(), "Map ingest failed: %s (keeping existing catalog)",
377	                 result.error_message.c_str());
378	    return;
379	  }
380	
381	  // ---- ⑤ 原子写出 + RViz Marker ----
382	  if (!WriteCatalogAtomic(result.catalog)) {
383	    RCLCPP_ERROR(get_logger(), "Failed to write catalog to '%s' (keeping existing catalog)",
384	                 output_stations_file_.c_str());
385	    return;
386	  }
387	  last_ingest_hash_ = ingest_hash;
388	  if (!msg->header.frame_id.empty()) {
389	    map_frame_id_ = msg->header.frame_id;
390	  }
391	
392	  RCLCPP_INFO(get_logger(),
393	              "Successfully ingested map and generated %s (%zu stations, %zu road nodes, "
394	              "%zu edges) [map_hash=%s]",
395	              output_stations_file_.c_str(), result.catalog.stations.size(),
396	              result.catalog.road_nodes.size(), result.catalog.edges.size(), map_hash.c_str());
397	
398	  if (publish_markers_) {
399	    PublishTopologyMarkers(result.catalog);
400	  }
401	}
