403	void MapIngestNode::PublishTopologyMarkers(const StationCatalog& catalog) {
404	  visualization_msgs::msg::MarkerArray array;
405	  const auto stamp = now();
406	
407	  // 先 DELETEALL 清残影：重新导入（地图更新）时上一批 Marker 全部作废。
408	  visualization_msgs::msg::Marker clear;
409	  clear.header.frame_id = map_frame_id_;
410	  clear.header.stamp = stamp;
411	  clear.ns = "topology_reset";
412	  clear.id = 0;
413	  clear.action = visualization_msgs::msg::Marker::DELETEALL;
414	  array.markers.push_back(clear);
415	
416	  int id = 0;
417	  const auto base_marker = [&](const std::string& ns, int type) {
418	    visualization_msgs::msg::Marker marker;
419	    marker.header.frame_id = map_frame_id_;
420	    marker.header.stamp = stamp;
421	    marker.ns = ns;
422	    marker.id = id++;
423	    marker.type = type;
424	    marker.action = visualization_msgs::msg::Marker::ADD;
425	    marker.pose.orientation.w = 1.0;
426	    // 永久驻留（lifetime=0）+ transient_local 发布：晚加入的 RViz 也能看到。
427	    return marker;
428	  };
429	
430	  // 端点查找表：折线退化（<2 点）时回退用站点/节点坐标补两个端点。
431	  std::unordered_map<std::string, std::pair<double, double>> endpoint_xy;
432	  for (const auto& node : catalog.road_nodes) {
433	    endpoint_xy[node.id] = {node.x, node.y};
434	    auto marker = base_marker("road_nodes", visualization_msgs::msg::Marker::SPHERE);
435	    marker.pose.position.x = node.x;
436	    marker.pose.position.y = node.y;
437	    marker.pose.position.z = 0.05;
438	    marker.scale.x = 0.15;
439	    marker.scale.y = 0.15;
440	    marker.scale.z = 0.15;
441	    marker.color = Color(0.65f, 0.65f, 0.65f, 0.9f);
442	    array.markers.push_back(marker);
443	  }
444	
445	  for (const auto& station : catalog.stations) {
446	    endpoint_xy[station.id] = {station.x, station.y};
447	    auto marker = base_marker("stations", visualization_msgs::msg::Marker::CYLINDER);
448	    marker.pose.position.x = station.x;
449	    marker.pose.position.y = station.y;
450	    marker.pose.position.z = 0.05;
451	    marker.scale.x = 0.3;
452	    marker.scale.y = 0.3;
453	    marker.scale.z = 0.1;
454	    marker.color = StationColor(station.type);
455	    array.markers.push_back(marker);
456	
457	    auto label = base_marker("station_labels", visualization_msgs::msg::Marker::TEXT_VIEW_FACING);
458	    label.pose.position.x = station.x;
459	    label.pose.position.y = station.y;
460	    label.pose.position.z = 0.5;
461	    label.scale.z = 0.25;
462	    label.color = Color(1.0f, 1.0f, 1.0f, 0.95f);
463	    label.text = station.id;
464	    array.markers.push_back(label);
465	  }
466	
467	  // 边：LINE_STRIP 沿真实 polyline 走廊中心线（而非两点直线）。
468	  for (const auto& edge : catalog.edges) {
469	    auto marker = base_marker("edges", visualization_msgs::msg::Marker::LINE_STRIP);
470	    marker.scale.x = 0.06;  // 线宽（米）
471	    marker.color = Color(0.1f, 0.8f, 0.9f, 0.9f);
472	    if (edge.polyline.size() >= 2) {
473	      marker.points.reserve(edge.polyline.size());
474	      for (const auto& point : edge.polyline) {
475	        geometry_msgs::msg::Point p;
476	        p.x = point.first;
477	        p.y = point.second;
478	        p.z = 0.03;
479	        marker.points.push_back(p);
480	      }
481	    } else {
482	      // 折线缺失的退化边：以两端点连线兜底，保证拓扑关系仍可视化。
483	      const auto from = endpoint_xy.find(edge.from);
484	      const auto to = endpoint_xy.find(edge.to);
485	      if (from == endpoint_xy.end() || to == endpoint_xy.end()) {
486	        continue;
487	      }
488	      geometry_msgs::msg::Point a;
489	      a.x = from->second.first;
490	      a.y = from->second.second;
491	      a.z = 0.03;
