#ifndef AMR_DISPATCHER_CORE__PLANNING__SKELETON_EXTRACTOR_HPP_
#define AMR_DISPATCHER_CORE__PLANNING__SKELETON_EXTRACTOR_HPP_

#include <vector>

#include "amr_dispatcher_core/planning/map_geometry_utils.hpp"
#include "amr_dispatcher_core/planning/safety_space_filter.hpp"

namespace amr_dispatcher_core::planning {

// 经典 Zhang-Suen 细化算法：每轮执行两个子步，迭代消除满足条件的边界
// 像素，直至得到 1 像素宽的骨架线。
// 输入 BinaryGrid：1 = 可通行安全区域，0 = 障碍 / 禁止区域。
// 输出 BinaryGrid：仅保留 1 像素宽的骨架线（1 保留为 1，其余置 0）。
BinaryGrid ZhangSuenThinning(const BinaryGrid& grid);

// 受保护剪枝参数。
struct PruneConfig {
  double min_branch_length_m = 0.5;  // 剪除短于此长度的死胡同末端毛刺
  double resolution = 0.05;          // 米/像素
};

// 在骨架上执行受保护的毛刺剪枝：
//   1. 寻找度数为 1 的端点（8 邻域中只有 1 个相邻骨架像素）。
//   2. 从端点向内追踪分支，直至遇到分叉点（8 邻域连通组数 >= 3）或
//      另一个端点（连通组数 <= 1）。分支推进方向按与来向夹角最小者选取
//      （直线延续优先于斜向逃逸），且优先命中分叉候选——避免固定环序把
//      斜向紧邻的旁侧结构排在直线之前，导致追踪横向逃逸到相邻主线。
//   3. 分支长度（像素数 × resolution）短于 min_branch_length_m 时：
//        - 若分支上任意像素与 protected_points 中某点的欧式距离 < 1.5 像素，
//          视为承载站点的受保护分支，强制豁免，不可剪除。
//        - 否则将分支像素（不含分叉点）全部置 0；若停止点仅因该分支而
//          呈现为分叉（剩余邻居经 4 邻接连通后为单一连通组），则停止点
//          作为冗余凸起一并剪除。
//   4. 迭代重复，直至不再有可删除的未受保护短毛刺。
// 注：分叉判据采用 8 邻域环上的连通组数（而非裸像素数），避免把紧邻正交
// 交叉点的直线像素误判为分叉、在主干上残留 1 像素凸起伪影。
// 返回剪枝后的新栅格（入参只读，不原地修改）。
BinaryGrid PruneSkeletonProtected(
    const BinaryGrid& skeleton, const std::vector<PixelCoord>& protected_points,
    const PruneConfig& config);

}  // namespace amr_dispatcher_core::planning

#endif  // AMR_DISPATCHER_CORE__PLANNING__SKELETON_EXTRACTOR_HPP_
=====
#ifndef AMR_DISPATCHER_CORE__PLANNING__SAFETY_SPACE_FILTER_HPP_
#define AMR_DISPATCHER_CORE__PLANNING__SAFETY_SPACE_FILTER_HPP_

#include <cstdint>
#include <vector>

#include "amr_dispatcher_core/planning/map_geometry_utils.hpp"

namespace amr_dispatcher_core::planning {

// 二值通过图：1 = 安全通行（自由空间），0 = 不可通行（障碍 / 未知 / 膨胀余量）。
struct BinaryGrid {
  uint32_t width = 0;   // 列数（像素）
  uint32_t height = 0;  // 行数（像素）
  // 行主序（index = row * width + col），长度应为 width * height。
  std::vector<uint8_t> data;

  // 像素坐标是否落在 [0, width) × [0, height) 内。
  bool IsValidPixel(int col, int row) const;

  // 越界（或 data 未初始化）时防御性返回 0（不可通行），
  // 与 MapGrid 的 GetValue 越界返回未知语义对齐：出图区域一律不放行。
  uint8_t GetValue(int col, int row) const;

  // 越界写入为无操作（no-op），不扩容不改尺寸。
  void SetValue(int col, int row, uint8_t val);
};

// 机器人尺寸腐蚀与自由空间过滤参数。
struct SafetyFilterConfig {
  double robot_radius_m = 0.25;  // 机器人半身半径（米）
  double safety_margin_m = 0.05; // 额外安全余量（米）
  // 格子值 >= occupied_threshold 视为障碍（与 nav_msgs/OccupancyGrid 一致，
  // 默认 65 介于"确定空闲"与"确定占用(100)"之间）。
  int8_t occupied_threshold = 65;
  // 未知格（-1）是否按障碍处理。默认 true：未知区域不放行。
  bool treat_unknown_as_obstacle = true;
};

// 将原始 MapGrid 过滤为二值通过图 BinaryGrid。
// 第一步：occupied_threshold 之上（以及可选的未知格）标记为初始障碍，其余为通行候选。
// 第二步：以 R = robot_radius_m + safety_margin_m 为半径做圆形核膨胀——
//         任何与初始障碍欧氏距离 <= R 的格子置 0（可通行区腐蚀）。
BinaryGrid FilterSafetySpace(const MapGrid& grid, const SafetyFilterConfig& config);

}  // namespace amr_dispatcher_core::planning

#endif  // AMR_DISPATCHER_CORE__PLANNING__SAFETY_SPACE_FILTER_HPP_

